-- NMS AA set for the dynamic items add-on (optional).
-- Copies of the four AA tables named nms_aa_*; the stock aa_* tables are not touched.
-- Turn it on with rule Custom:NmsAATables = true and restart the zones (they load AAs at boot).
-- Custom:NmsCustomAAs also loads the AAs NMS added (needs nms_aa_custom_spells.sql and NMS client files).
-- Built against PEQ database version 9328. Safe to run again: it drops and recreates the nms_aa_* tables.

DROP TABLE IF EXISTS `nms_aa_ability`;
CREATE TABLE `nms_aa_ability` LIKE `aa_ability`;

DROP TABLE IF EXISTS `nms_aa_ranks`;
CREATE TABLE `nms_aa_ranks` LIKE `aa_ranks`;

DROP TABLE IF EXISTS `nms_aa_rank_effects`;
CREATE TABLE `nms_aa_rank_effects` LIKE `aa_rank_effects`;

DROP TABLE IF EXISTS `nms_aa_rank_prereqs`;
CREATE TABLE `nms_aa_rank_prereqs` LIKE `aa_rank_prereqs`;

